<script setup lang="ts">
import { computed,onMounted,ref } from "vue";import { Pige360SessionClient,type ApiProblem } from "@pige360/auth";type Row=Record<string,any>;const api=new Pige360SessionClient();const ready=ref(false),auth=ref(false),busy=ref(false),error=ref(""),email=ref(""),password=ref("");const brand=ref<Row>({}),catalog=ref<Row>({releases:[]});const filter=ref("all");const school=computed(()=>brand.value.short_name||brand.value.trade_name||brand.value.legal_name||"Instituição");const artifacts=computed(()=>catalog.value.releases?.flatMap((r:Row)=>r.artifacts.map((a:Row)=>({...a,release:r}))).filter((a:Row)=>filter.value==='all'||a.platform?.startsWith(filter.value))||[]);function msg(e:unknown){const p=(e as Error&{problem?:ApiProblem})?.problem;return p?.detail||(e instanceof Error?e.message:"Erro inesperado");}function apply(){document.documentElement.style.setProperty('--brand-primary',brand.value.primary_color||'#006D77');document.documentElement.style.setProperty('--brand-secondary',brand.value.secondary_color||'#0D1B2A');document.title=`${school.value} — Aplicativos`;}
async function load(){const b=await api.request<Row>("/branding/current");brand.value=b.payload||b;catalog.value=await api.request<Row>("/apps/catalog");apply();}async function boot(){try{await api.initialize();auth.value=!!api.tokens;if(auth.value)await load();}catch(e){error.value=msg(e);}finally{ready.value=true;}}async function login(){try{await api.login(email.value,password.value);auth.value=true;await load();}catch(e){error.value=msg(e);}}async function logout(){await api.logout();auth.value=false;}
async function download(a:Row){busy.value=true;error.value="";try{const headers=new Headers({Accept:'application/octet-stream'});if(api.tokens)headers.set('Authorization',`Bearer ${api.tokens.access_token}`);const r=await fetch(api.url(`/apps/releases/${a.release.id}/download?artifact_id=${encodeURIComponent(a.id)}`),{headers});if(!r.ok)throw new Error(`Falha no download (${r.status})`);const digest=r.headers.get('X-Artifact-SHA256');if(digest&&digest!==a.sha256)throw new Error('Checksum informado pelo servidor diverge do catálogo.');const blob=await r.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=a.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=msg(e);}finally{busy.value=false;}}onMounted(boot);
</script>
<template><div v-if="!ready" class="center">Inicializando central…</div><div v-else-if="!auth" class="login-page"><form class="login-card" @submit.prevent="login"><div class="mark">⇩</div><span class="eyebrow">Aplicativos da escola</span><h1>Central privada de downloads</h1><label>E-mail<input v-model="email" type="email" required></label><label>Senha<input v-model="password" type="password" required></label><p v-if="error" class="flash error">{{error}}</p><button class="primary">Entrar</button></form></div><div v-else class="mobile-shell"><header><div class="brand"><div class="mark">⇩</div><div><strong>{{school}}</strong><small>Central de aplicativos</small></div></div><button class="ghost" @click="logout">Sair</button></header><main><div v-if="error" class="flash error">{{error}}</div><section class="welcome"><span class="eyebrow light">Distribuição privada</span><h1>Aplicativos oficiais</h1><p>Artefatos versionados, auditados e verificados por SHA-256.</p></section><div class="filters"><button v-for="p in ['all','android','ios','windows','linux','macos','pwa']" :key="p" :class="{active:filter===p}" @click="filter=p">{{p}}</button></div><section class="download-grid"><article class="panel artifact" v-for="a in artifacts" :key="a.id"><div class="platform">{{a.platform}}</div><h2>{{a.app_product}}</h2><p>{{a.filename}}</p><dl><div><dt>Versão</dt><dd>{{a.release.version}}</dd></div><div><dt>Canal</dt><dd>{{a.release.channel}}</dd></div><div><dt>Arquitetura</dt><dd>{{a.architecture}}</dd></div><div><dt>SHA-256</dt><dd class="hash">{{a.sha256}}</dd></div></dl><button class="primary" :disabled="busy" @click="download(a)">Baixar</button></article><div v-if="!artifacts.length" class="panel empty-state"><h2>Nenhum aplicativo publicado</h2><p>A escola ainda não disponibilizou artefatos neste filtro.</p></div></section></main></div></template>
